	[11721] = {
		Text = "1.舰队联赛分为报名期、备战期、等待期、对战期、领奖期\n2.报名期[每周五22:00~每周一24:00]:舰队人数达15人将自动报名(期间更换舰队仍可参与)\n3.备战期[每周二00:00~24:00]:统帅、士官可于此期间进行防守配置(期间更换舰队将无法参与)\n4.等待期[每周三四五00:00~10:00]:可观看敌我双方的防守配置(期间更换舰队将无法参与)\n5.对战期[每周三四五10:00~22:00]:每人每日有三次攻击机会，合理分配击破敌方守备获得分数\n根据三场战斗的总分进行舰队排名、个人排名\n6.领奖期[每周三四五22:00后]:每场根据胜负结算单场奖励，每周根据舰队排名、个人排名结算排行奖励\n7.联赛商店:进行战斗时获得的积分，可于商店兑换稀有道具",
	},
	[20137] = {
		Text = "来打场雪仗吧~",
	},
	[20139] = {
		Text = "把你也做成玩具~",
