	},
	[100634] = {
		Text = "1.每周会进行两轮跨服排位\n2.第一轮为：周一06:00~周三22:00，报名截止：周一01:00\n3.第二轮为：周五06:00~周日22:00，报名截止：周五01:00\n4.第一次报名后将开启自动报名，若连续两轮未参与则取消自动报名",
	},
