	[500281] = {
		Text = "自选机率UP",
	},
	[500282] = {
		Text = "自选机率UP乘员",
	},
	[500283] = {
		Text = "选定的角色获得机率提升！",
	},
	[500285] = {
		Text = "取消机率UP",
	},
	[500286] = {
		Text = "已更换机率UP乘员",
	},
	[500287] = {
		Text = "已取消机率UP设定",
	},
	[590167] = {
		Text = "1、舰长可使用「乘员券」进行招募，数量不足时，可改为消耗「碎星」。\n2、保底计数为100次，第100抽必定获得一位乘员；触发保底后，计数将重新累积。\n3、未达100抽前，即使途中招募到任何乘员，也不会重置保底计数。\n4、设定「机率UP乘员」后，该乘员的获得机率将提升至0.8%，其余乘员则平均分配剩余的0.7%机率。\n5、触发保底时，不会必定获得目前设定的「机率UP乘员」。\n6、未设定「机率UP乘员」时，所有乘员的获得机率皆为平均分配。设定后，舰长仍可随时切换指定乘员，或于选择介面右下角点击「重置」，解除目前的机率UP设定。\n7、保底计数将持续保留，不会因活动更替或奖池更新而重置。\n8、奖池内各项目显示机率皆采四舍五入至小数点后第二位，因此显示数值加总后可能存在些微误差，不一定恰好为100%。\n9、于本奖池进行招募时，不会获得「乘员姬分券」。",
	},
