	[500359] = {
		Text = "童话作家・西西雅",
	},
	[500361] = {
		Text = "玩家等级达到40等后领取",
	},
	[100027] = {
		Text = "1、舰长消耗道具可以在奖池中抽取出对应的道具\n2、限量品项与终极大奖皆包含在限量奖励中。\n3、本奖池保底分成「限量保底」与「终极保底」，当抽数达到「限量保底」次数时，会必定从限量奖励中抽取其一。\n4、若舰长提前抽中限量奖励时，会将「限量保底」次数进行重置。\n5、若抽数达到「终极保底」时，必定获得终极大奖。\n6、获得终极大奖后，会将所有限量品项次数进行重置。",
	},
