	[601801] = {
		Text = "将门撞开",
	},
	[601802] = {
		Text = "看瑟蕾雅的笔记求救",
	},
	[601803] = {
		Text = "从阳台闯入",
	},
	[601804] = {
		Text = "试探",
	},
	[601805] = {
		Text = "开灯",
	},
	[601806] = {
		Text = "",
	},
	[601807] = {
		Text = "这只是简单的热身运动吧！ ？",
	},
	[601808] = {
		Text = "",
	},
	[601809] = {
		Text = "",
	},
	[601810] = {
		Text = "和西西雅健走吧",
	},
	[601811] = {
		Text = "和西西雅丢球吧",
	},
	[601812] = {
		Text = "和西西雅骑车吧",
	},
	[601813] = {
		Text = "和西西雅聊聊生活",
	},
	[601814] = {
		Text = "",
	},
	[601815] = {
		Text = "",
	},
	[601816] = {
		Text = "你在干什么啊！西西雅！",
	},
	[601817] = {
		Text = "",
	},
	[601818] = {
		Text = "",
	},
	[601819] = {
		Text = "怀疑西西雅",
	},
	[601820] = {
		Text = "闭上眼睛嘟起嘴",
	},
	[601821] = {
		Text = "坚持不闭眼",
	},
	[601822] = {
		Text = "闭上双眼",
	},
	[601823] = {
		Text = "",
	},
	[601824] = {
		Text = "",
	},
	[601825] = {
		Text = "……",
	},
	[601826] = {
		Text = "",
	},
	[601827] = {
		Text = "",
	},
	[611801] = {
		Text = "动作干净俐落，判定为惯犯，总之先报警吧。",
	},
	[611802] = {
		Text = "把那本笔记本给我……",
	},
	[611810] = {
		Text = "就只是走路而已，这也能算运动吗？",
	},
	[611811] = {
		Text = "不就是丢球吗？能有多难呢？",
	},
	[611812] = {
		Text = "骑车的方式都在书上看过了，我已经完全理解了。",
	},
	[611819] = {
		Text = "我从不说谎，随便怀疑人的船长会被讨厌喔。",
	},
	[611820] = {
		Text = "这种剧情现实怎么可能出现，用大脑多想想吧？",
	},
	[611821] = {
		Text = "快闭上眼，不然我就把船长打晕。",
	},
