	[2088] = {
		Text = "灵活运用炸药与定点火药，搭配寻找虫洞，更快完成连线、赢取大奖！\n\n1. 每局开始可获得免费炸药3次、定点火药1次。\n2. 使用炸药可随机开启5个格子。\n3. 使用定点火药可自由开启任一格。\n4. 完成宾果连线可获得对应奖励。\n5. 完成8条连线可获得宾果大奖。\n6. 获得大奖后可选择重置盘面，开启新挑战。\n7. 使用「寻找虫洞」可消耗星钻随机开启1格。\n8. 寻找虫洞次数越多，星钻消耗越高：\n     1～3次：35星钻\n     4～5次：70星钻\n     6～7次：105星钻\n     8次：140星钻\n     9次：175星钻",
