	},
	[1706] = {
		Text = "1、线上期间每分钟可积累一定数量的金币与聚变之证奖励，每10分钟可积累获得一定数量的碎星、技能与机群奖励。\n2、获取奖励的品质和数量与您当前的主线关卡进度相关。\n3、放置奖励的收集时间上限为24小时，24小时后将不再积累奖励，请注意领取。\n4、每次等待冷却时间，可以获得2小时放置奖励。",
	},
	[100789] = {
		Text = "1、舰长将组织「时空管理队」，深入未知的宇宙星域进行探索。\n2、透过与其他舰长进行交涉，战胜后可将其招募为管理队队员，提升探索奖励。\n3、若该名舰长已加入他人的队伍，则需战胜对方的管理队队长后，才能成为新队长。\n4、每名队员将在 7 天后自动离队，舰长也可自行选择是否提早结束同行。\n5、透过与自身的队长交涉，或请求他人帮助可恢复自由之身，重新成为管理队队长。",
	},
