	[100801] = {
		Text = "队长资讯",
	},
	[100802] = {
		Text = "1、随着时间获得奖励，可获得的品质和数量与您当前的主线关卡进度相关。\n2、基础探索奖励倍率为 100%，可透过招募队员来提升奖励倍率。\n3、自身为时空管理队长时，将获得额外奖励倍率；受雇于他人时，将失去此加成。\n4、探索奖励的储存舱收集上限为10小时，达上限后将不再累积奖励，请注意领取。",
	},
