	[101111] = {
		Text = "亲爱的玩家您好：\n\n针对功能推出前已完成相关关卡的玩家，我们已依照您的关卡通关纪录，计算应获得的碎星数量，并透过本信件进行补发。\n\n请于信件有效期限内领取附件奖励，感谢您的支持与陪伴，祝您游戏愉快！",
