	[590166] = {
		Text = "1、舰长可使用「姬绊劵」进行招募，获得奖池内对应的道具与乘员；当姬绊劵不足时，可消耗星钻进行招募。\n2、本招募属机率型招募，未设置保底机制。\n3、每进行1次招募，可获得1点「乘员姬分券」，可至「兑换商店」兑换指定乘员。\n4、活动结束后，「乘员姬分券」不会消失，可持续累积至后续活动兑换使用。\n5、奖池内各类别及各项目之显示机率皆采四舍五入至小数点后第二位，因此总机率加总后可能略有误差，并非100%。\n6、活动结束后，本次活动乘员将于后续不定期加入常驻乘员招募奖池。",
	},
