	},
	[500217] = {
		Text = "1、舰长仅可消耗碎星进行招募，获得奖池内对应的道具与乘员。\n2、于招募期间内，可随时更换自选乘员，自选项目不计入也不影响机率。\n3、招募期间内，即使提前获得任何乘员，亦不会影响自选保底次数。\n4、奖池内各类别及各项目之显示机率皆采四舍五入至小数点后第二位，因此总机率加总后可能略有误差，并非100%。\n5、本奖池最多可进行4次十连招募，完成第4次十连招募后将自动关闭，并于第4次十连招募必定获得自选乘员。\n6、于本奖池进行招募时，不会获得「乘员姬分券」。",
	},
	[590106] = {
		Text = "再招募 <color=#f8acca>{0}</color> 次必得乘员角色",
	},
	[601517] = {
