	},
	[500223] = {
		Text = "1、舰长仅可消耗星钻进行招募，获得奖池内对应的道具与乘员。\n2、奖池内各类别及各项目之显示机率皆采四舍五入至小数点后第二位，因此总机率加总后可能略有误差，并非100%。\n3、本奖池最多可进行4次十连招募，完成第4次十连招募后将自动关闭，并于第4次十连招募必定获得超级大奖乘员。\n4、于本奖池进行招募时，不会获得「乘员姬分券」。\n5、若累积消耗活动处于开启状态时，于本奖池进行招募所消耗之星钻将会计入。",
	},
