	[590898] = {
		Text = "沐光礼包VII",
	},
	[613420] = {
		Text = "欢迎，来到我的芬布尔之冬。",
	},
	[613421] = {
		Text = "嗯哼?～",
	},
	[613422] = {
		Text = "嗯，做得不错。",
	},
	[613423] = {
		Text = "这种想法，只会给你带来危险喔。",
	},
	[613424] = {
		Text = "有点意思呢。",
	},
	[613425] = {
		Text = "你很有当小丑的天赋喔。",
	},
	[613426] = {
		Text = "唔......还不够吗？",
	},
	[613427] = {
		Text = "我不想.......接受这种事。",
	},
	[613428] = {
		Text = "再说一次，这次说的简单一点。",
	},
	[613429] = {
		Text = "看到我了还不行礼吗？",
	},
	[613430] = {
		Text = "让我也看看。",
	},
	[613431] = {
		Text = "衣服都被你弄乱了！",
	},
	[613432] = {
		Text = "再这样乱摸，小心我把你冰起来。",
	},
	[613433] = {
		Text = "唔！都怪你让我发出了怪声音......",
	},
	[613434] = {
		Text = "让你许一个愿望吧，当然这次，我会在能力所及的范围内去做的。",
	},
	[613435] = {
		Text = "居然还能散发出如此光辉吗？真是......愚蠢又有趣的男人。",
	},
	[613436] = {
		Text = "无畏寒冷、创造奇迹的旅人，这一次又要写下什么童话呢？",
	},
	[4395] = {
		Text = "Kayla",
	},
	[9805] = {
		Text = "<color=#e82b4f>还剩：{0}天</color>",
	},
