	},
	[600901] = {
		Text = "普通的动物就好了",
	},
	[600902] = {
		Text = "超巨型狩猎才对味",
	},
	[600903] = {
		Text = "简单的抓一只松鼠呢？",
	},
	[600904] = {
		Text = "捕兽陷阱？",
	},
	[600905] = {
		Text = "",
	},
	[600906] = {
		Text = "",
	},
	[600907] = {
		Text = "上……上去哪里！ ？",
	},
	[600908] = {
		Text = "",
	},
	[600909] = {
		Text = "",
	},
	[600910] = {
		Text = "咸奶油面包？",
	},
	[600911] = {
		Text = "菠萝面包？",
	},
	[600912] = {
		Text = "巧克力面包？",
	},
	[600913] = {
		Text = "详细的说明巨狼的故事",
	},
	[600914] = {
		Text = "简短扼要的说明",
	},
	[600915] = {
		Text = "",
	},
	[600916] = {
		Text = "你到底是狼还是狐狸啊？",
	},
	[600917] = {
		Text = "",
	},
	[600918] = {
		Text = "",
	},
	[600919] = {
		Text = "雪球和木炭的神话",
	},
	[600920] = {
		Text = "诸神黄昏",
	},
	[600921] = {
		Text = "小红帽？",
	},
	[600922] = {
		Text = "好了，那现在是……",
	},
	[600923] = {
		Text = "",
	},
	[600924] = {
		Text = "",
	},
	[600925] = {
		Text = "很可惜的不是喔。",
	},
	[600926] = {
		Text = "",
	},
	[600927] = {
		Text = "",
	},
	[610901] = {
		Text = "虽然吃得饱就行，但是普通可不够呀！",
	},
	[610902] = {
		Text = "下次就轮到小公鸡吃掉太阳了。",
	},
	[610903] = {
		Text = "还是白白胖胖的最好了。",
	},
	[610910] = {
		Text = "嗯～口水都要流下来了～",
	},
	[610911] = {
		Text = "曲奇饼？是一种新型的面包吗？总之先给我！",
	},
	[610912] = {
		Text = "巧克力……现在想起来还会浑身发抖……",
	},
	[610919] = {
		Text = "不知道月亮吃起来好不好吃？",
	},
	[610920] = {
		Text = "人类的神话跟伊尔瓦还真像呢！",
	},
	[610921] = {
		Text = "这是伊尔瓦听过最烂的故事了！",
	},
	[611501] = {
		Text = "三明治就只是把食物叠在一起而已嘛！",
	},
	[611502] = {
		Text = "还是大玩偶对秋比最好了！",
	},
	[611503] = {
		Text = "大玩偶喜欢喝机油吗？",
	},
	[611510] = {
		Text = "下次可以让秋比修飞船呦！",
	},
	[611511] = {
		Text = "硬梆梆入侵秋比的家了！",
	},
	[611512] = {
		Text = "说不定硬邦邦也喜欢松饼。",
	},
	[611519] = {
		Text = "秋比…一点都…不怕…鬼故事…",
	},
	[611520] = {
		Text = "以后想要天天都吃这个！",
	},
	[611521] = {
		Text = "秋比也想要去看看那边！",
	},
	[613025] = {
		Text = "狩猎时间",
	},
	[613026] = {
		Text = "巨狼神话",
	},
	[613027] = {
		Text = "卡在雪中的巨狼",
	},
	[613043] = {
		Text = "秋比的元气日常",
	},
	[613044] = {
		Text = "机器人医生",
	},
	[613045] = {
		Text = "不一样的街道",
	},
	[613304] = {
		Text = "唔......确定吗？",
	},
	[613306] = {
		Text = "唔......令人头痛呢。",
	},
	[613367] = {
		Text = "全身上下都在高潮的刺激感......唔！",
	},
	[613387] = {
		Text = "唔喔喔！",
	},
	[613437] = {
		Text = "狩猎！开始啦！",
	},
	[613438] = {
		Text = "听懂啦！哈哈哈！ ......什么意思来着？",
	},
	[613439] = {
		Text = "喔喔！很不错嘛？",
	},
	[613440] = {
		Text = "我闻到危险的味道了。",
	},
	[613441] = {
		Text = "太好啦！再来再来！",
	},
	[613442] = {
		Text = "嘎啊！再这样我会咬你喔！",
	},
	[613443] = {
		Text = "切......真没意思。",
	},
	[613444] = {
		Text = "唔......我要回家了。",
	},
	[613445] = {
		Text = "嗯？什么意思？",
	},
	[613446] = {
		Text = "早～安～",
	},
	[613447] = {
		Text = "我闻到有趣的东西了，让我咬咬看！",
	},
	[613448] = {
		Text = "身上都沾满你的味道了啦！",
	},
	[613449] = {
		Text = "还要摸的话就拿面包来交换！",
	},
	[613450] = {
		Text = "你摸太多了！换我摸你！",
	},
	[613451] = {
		Text = "有变化吗？吃起来还是像鸡肉一样啊？",
	},
	[613452] = {
		Text = "变得更强，变得更快，然后一口将太阳吞掉！",
	},
	[613453] = {
		Text = "你越来越像个合格的狩猎者了呢！",
	},
	[613454] = {
		Text = "让本人处理，真是大材小用呢。",
	},
	[613455] = {
		Text = "嗯哼。",
	},
	[613456] = {
		Text = "勉勉强强呢",
	},
	[613457] = {
		Text = "如果是你的点子的话，那本人倒也不意外了。",
	},
	[613459] = {
		Text = "愚蠢的人类......",
	},
	[613460] = {
		Text = "唉......无所谓了。",
	},
	[613461] = {
		Text = "呜......不要......",
	},
	[613462] = {
		Text = "完全无法理解，蠢死了。",
	},
	[613463] = {
		Text = "贵安。",
	},
	[613464] = {
		Text = "喔？那是什么，本人允许你让我知道。",
	},
	[613465] = {
		Text = "小心手指被折断喔。",
	},
	[613466] = {
		Text = "有所觉悟了吗？",
	},
	[613467] = {
		Text = "本人应该没有让你停吧？",
	},
	[613468] = {
		Text = "恭喜你，无趣的冒险又向前一步了喔。",
	},
	[613469] = {
		Text = "这样子还没满足吗？好吧，只好再陪你一下了。",
	},
	[613470] = {
		Text = "现在夸奖本人的话，或许是好时机喔。",
	},
	[613529] = {
		Text = "唔......",
	},
	[613545] = {
		Text = "唔......",
	},
	[613568] = {
		Text = "唔......渐渐习惯这种感觉了呢。",
	},
	[613573] = {
		Text = "请靠近一点，让我来为您指引方向。",
	},
	[613574] = {
		Text = "我明白了。",
	},
	[613575] = {
		Text = "嗯。",
	},
	[613576] = {
		Text = "嗯......",
	},
	[613577] = {
		Text = "谢谢你......",
	},
	[613578] = {
		Text = "唔......请让我思考一下......",
	},
	[613579] = {
		Text = "抱歉......让您看到我没用的一面了。",
	},
	[613580] = {
		Text = "对不起......我会再努力的......",
	},
	[613581] = {
		Text = "欸......？是这样吗......？",
	},
	[613582] = {
		Text = "早安，舰长先生，今天有什么我可以帮忙的吗？",
	},
	[613583] = {
		Text = "啊！一不小心就看得太入迷了，不好意思......",
	},
	[613584] = {
		Text = "唔！",
	},
	[613585] = {
		Text = "这样......就会感觉到温暖吗？",
	},
	[613586] = {
		Text = "不好意思......我可以......要求更多吗......？",
	},
	[613587] = {
		Text = "闪闪发光......虽然也不是全都是美好的回忆，但就像是那片天空呢。",
	},
	[613588] = {
		Text = "舰长先生也像是太阳一般温暖呢......",
	},
	[613589] = {
		Text = "您总是能带来无数的奇迹呢......",
	},
	[613590] = {
		Text = "居然要一个病人来帮你吗......？我可不擅长做这种事喔。",
	},
	[613591] = {
		Text = "好～好～",
	},
	[613592] = {
		Text = "随便你吧。",
	},
	[613593] = {
		Text = "连作家都不敢写出如此愚蠢的想法呢。",
	},
	[613594] = {
		Text = "干嘛偷看我，才没有在笑。",
	},
	[613595] = {
		Text = "安静一点。",
	},
	[613596] = {
		Text = "反正不是第一次了，无所谓吧......",
	},
	[613597] = {
		Text = "......",
	},
	[613598] = {
		Text = "出乎意料的发展。",
	},
	[613599] = {
		Text = "打招呼的话就省了，不要打扰我。",
	},
	[613600] = {
		Text = "拿过来一点，我看不清楚，不要挡住我。",
	},
	[613601] = {
		Text = "不要打扰我看书就好了。",
	},
	[613602] = {
		Text = "你不觉得有点热吗，去把暖气关了。",
	},
	[613603] = {
		Text = "唔！不能等晚上吗？",
	},
	[613604] = {
		Text = "做得不错，我帮你写成一篇故事吧，想要取什么名字呢？",
	},
	[613605] = {
		Text = "就像童话一般的发展呢，但童话可是比现实更多无谓的悲剧喔，谨慎一点吧。",
	},
	[613606] = {
		Text = "我现在可以回去休息了吗？实在是不想动......",
	},
	[613607] = {
		Text = "老子！登场啦！",
	},
	[613608] = {
		Text = "总之就是先开枪吧？还是后开枪？",
	},
	[613609] = {
		Text = "哇喔——太厉害了吧！",
	},
	[613610] = {
		Text = "欸？这是玩笑吧？这应该是玩笑吧！ ？",
	},
	[613611] = {
		Text = "哼哼哼～呀啊！兄弟你在那边多久了！",
	},
	[613612] = {
		Text = "啊啊！信不信老子把你绑在铁轨上！",
	},
	[613613] = {
		Text = "唔......人家......很抱歉......",
	},
	[613614] = {
		Text = "……这样啊。",
	},
	[613615] = {
		Text = "你说的东西老子一个字都听不懂！哈哈哈！",
	},
	[613616] = {
		Text = "哟，兄弟！",
	},
	[613617] = {
		Text = "哈哈！让老子瞧瞧你的惊天计画！",
	},
	[613618] = {
		Text = "都是兄弟，想摸的话跟老子说就好了嘛！",
	},
	[613619] = {
		Text = "小心擦枪走火喔，哈哈，开玩笑的。",
	},
	[613620] = {
		Text = "咿呀！尾巴......不可以......",
	},
	[613621] = {
		Text = "呀哈！跑快一点！敌人追上来拉～",
	},
	[613622] = {
		Text = "兄弟，做得太好啦！作为奖励，可以给你摸一次尾巴喔！",
	},
	[613623] = {
		Text = "啊啊啊啊！感觉诅咒在扩散......我...我开玩笑的啦！你不要那么紧张啦！",
	},
