	[1699] = {
		Text = "尚未加入舰队",
	},
	[1701] = {
		Text = "1、共5个技能槽位，随主线关卡进度逐渐解锁。\n2、非活动类型的技能可以通过商店抽卡获得。\n3、消耗1个技能道具解锁对应技能，消耗技能道具或技能碎片可升级对应技能。\n4、技能满级后，溢出的技能道具可以进行合成，每3个相同的技能道具可以合成获得随机一个已解锁的高一品质的技能道具。\n5、最高品质的技能无法进行合成。",
	},
	[1702] = {
		Text = "1、共5个机群槽位，随主线关卡进度逐渐解锁。\n2、机群上阵后启动上阵效果，相同种族的机群上阵效果不可叠加，取最高品质效果。\n3、非活动类型的机群碎片可以通过抽卡获得。\n4、消耗1个机群碎片解锁对应机群，消耗额外机群碎片升级对应机群。\n5、机群满级后，溢出的机群碎片可以进行合成，每3个相同的机群碎片可以合成获得随机一个已解锁的高一品质的机群碎片。\n6、最高品质的机群无法进行合成。",
	},
	[1703] = {
		Text = "1、挑战副本需消耗对应副本入场钥匙。\n2、副本入场钥匙每天0点会补至上限。\n3、各副本开放条件不同，可点击未开放副本查看解锁条件。\n4、各副本获得奖励方式不同，详见各副本说明。",
	},
	[1704] = {
		Text = "1、活动期间，您在游戏内付费或消耗星钻购买礼包可累计活动进度。\n2、储值星钻不被计算在活动消费中。\n3、活动奖励将在活动结束时停止领取，请注意及时领取奖励。",
	},
	[1705] = {
		Text = "1、活动期间，您每天在游戏内付费或消耗星钻购买礼包可累计活动进度。\n2、储值星钻不被计算在活动消费中。\n3、活动奖励将在活动结束时停止领取，请注意及时领取奖励。",
	},
	[1707] = {
		Text = "1、消耗金币可提升情绪聚变装置升级进度阶段。升级进度阶段升满时，可按下升级按钮进行升级。等待一段时间，情绪聚变装置会完成升级，提升抽出高品质装备的机率。\n2、升级等待时间可使用加速券或碎星加速，亦可以等待冷却时间跳过一段时间。",
	},
	[1708] = {
		Text = "1、每次挑战过程中，击败指定等级的云殿守卫时，便可为舰队带回1个「云锦宝箱」，最多可带回3个「云锦宝箱」。\n2、战胜更高等级的云殿守卫时，有机率可带回1个珍贵的「彩云宝箱」。\n3、「云锦宝箱」和「彩云宝箱」各有每日可领取的上限，该上限随舰队等级而提升。\n4、退出舰队时，尚未开启的宝箱将会全数清空，请即时领取。",
	},
	[1709] = {
		Text = "笼罩金殿的星穹之门涌动着不寻常的光芒，星冠翎卫・奥菲亚正蓄势待发。快驾驭飞船征服高傲之冕，用绝对力量抑制她的神圣与狂妄！",
	},
	[1710] = {
		Text = "1、每日挑战奖励：每日重置后完成一次挑战，即可获得的固定奖励，每日仅可获得一次。\n2、排名奖励：每日0点，根据您昨日的最高伤害排名，通过信件发送排名奖励。\n3、伺服器进度奖励：当日本伺服器中所有玩家的最高伤害，累计突破达门槛后，将于次日0点透过信件发送特殊奖励。",
	},
