	[2200] = {
		Text = "1、玩家消耗道具可以在奖池中抽出对应的道具。\n2、初始时由最下层奖池开始抽奖，抽到该层的「晋级奖励」后即可切换往上一层的奖池继续抽奖。\n3、由下往上，第一、二、三、四层的保底次数分别为30、150、175和150，玩家抽取次数「达到保底次数」时，下一次抽取「必定」会抽中当前层次的晋级奖励。\n4、玩家提前抽中晋级奖励时，会将保底次数进行重置。\n5、抽中最上层的晋级奖励后，会将所有限量道具次数重置，并移至最下层奖池开起下一轮抽奖。",
	},
