		Text = "已摆放在博物馆内",
	},
	[2968] = {
		Text = "<抢夺支援>",
	},
	[2969] = {
		Text = "1.每个私人博物馆拥有4个展示区，公共博物馆户外展区有10个展示区。\n2.玩家最多可展示5个不同的已解锁飞船在不同博物馆之展示间。\n3.展示飞船可获得展示币，单次展示时间越长，获取速率越高。\n4.展示飞船可获得该飞船之研究经验，提升飞船研究等级可获得额外属性加成，亦可使用科学期刊提升指定飞船之研究等级。\n5.展示飞船可获得游客捐赠奖励，不同飞船之对应奖励不同，单次展示时间越长，获取速率越高。\n6.单次展示时间到达8小时后，将不会获得任何收益，12小时后飞船将被自动撤展。\n7.飞船单日总有奖展示时间达12小时后，该飞船获得展示币之收益减半，且不会获得研究经验与游客捐赠奖励。\n8.玩家可抢夺他人展示中之飞船，掠夺时不可移动，掠夺成功后，该飞船展示强制中止，且参与掠夺之玩家能获得部分展示币收益。\n9.每次掠夺成功时，玩家获得一层连战疲劳，层数越高减少之属性越多，每30分钟下降一层。\n10.掠夺失败时，10分钟内不可再次掠夺。\n11.玩家可在本人博物馆收取展示管理费，其他玩家若选择上交管理费，可请博物馆主人代为驻守，且博物馆主人无法掠夺有上交管理费之玩家。",
	},
