	[14030] = {
		Text = " 1.报名时段与挑战限制\n．报名时间： 每周一 00:00 至 24:00。\n．限制说明： 于竞赛报名期间内，矿场将暂停开放，无法进入挑战。\n 2.新创舰队报名资格\n．参赛说明： 报名期间内新创立之舰队，仍具备参加竞赛与进入舰队排行榜之资格。\n．奖励限制： 新创舰队之成员于该周无法领取「每周奖励」。\n 3.报名结束后更换舰队，相关权益如下：\n．奖励领取： 仍可领取原舰队结算之每周奖励。\n．个人排行： 可正常参与新舰队的个人竞赛，并计入个人排行榜。\n．舰队排行： 当周其个人积分将不计入新舰队的「舰队排行榜」。",
	},
