	[20001] = {
		Text = "(咕噜噜—)",
	},
	[20002] = {
		Text = "欢迎来到—蒸汽星球！",
	},
	[20003] = {
		Text = "为您提供—微笑服务！",
	},
	[20004] = {
		Text = "(哔—嗡—)",
	},
	[20005] = {
		Text = "扫描—确认目标—",
	},
	[20006] = {
		Text = "警告…电量过低…",
	},
	[20007] = {
		Text = "(嗡嗡嗡—)",
	},
	[20008] = {
		Text = "执行—强制驱逐！",
	},
	[20009] = {
		Text = "小心我的—机械爪！",
	},
	[20010] = {
		Text = "(噗啾—)",
	},
	[20011] = {
		Text = "好冷…我的行李呢…？",
	},
	[20012] = {
		Text = "要看看背包里的宝物吗？",
	},
	[20013] = {
		Text = "(沙沙—喀啦—)",
	},
	[20014] = {
		Text = "我的手…好像快断了…",
	},
	[20015] = {
		Text = "是谁…偷咬了我一口…？",
	},
	[20016] = {
		Text = "(叩！叩！)",
	},
	[20017] = {
		Text = "坚守岗位！不准通行！",
	},
	[20018] = {
		Text = "让我来敲碎你的脑壳！",
	},
	[20019] = {
		Text = "(扑哧—)",
	},
	[20020] = {
		Text = "荒野里有新鲜的气味！",
	},
	[20021] = {
		Text = "我的声纳已经锁定你了！",
	},
	[20022] = {
		Text = "(哐啷—)",
	},
	[20023] = {
		Text = "尝尝我铁球的威力！",
	},
	[20024] = {
		Text = "碾碎…所有入侵者！",
	},
	[20025] = {
		Text = "(咯咯咯—)",
	},
	[20026] = {
		Text = "荒野的亡魂啊…听我号令…",
	},
	[20027] = {
		Text = "你的骨头…看起来很不错…",
	},
	[20028] = {
		Text = "(沙沙声—)",
	},
	[20029] = {
		Text = "沉睡了几千年…好困啊……",
	},
	[20030] = {
		Text = "要把你一起绑成木乃伊吗？",
	},
	[20031] = {
		Text = "(低吼—)",
	},
	[20032] = {
		Text = "目标锁定—进入狩猎模式！",
	},
	[20033] = {
		Text = "警告！别靠近我的地盘！",
	},
	[20034] = {
		Text = "(嘶嘶—)",
	},
	[20035] = {
		Text = "打扰法老王安宁的人，死！",
	},
	[20036] = {
		Text = "让权杖引导你的灵魂吧。",
	},
	[20037] = {
		Text = "小怪发话占位",
	},
