	[20100] = {
		Text = "(齿轮转动声—)",
	},
	[20101] = {
		Text = "必须…保护主人…",
	},
	[20102] = {
		Text = "绝不让你前进！",
	},
	[20103] = {
		Text = "铁拳…打飞敌人！",
	},
	[20104] = {
		Text = "主人…你到哪去了？",
	},
	[20105] = {
		Text = "太阳，将一切点亮",
	},
	[20106] = {
		Text = "月亮…消逝于黑暗…",
	},
	[20107] = {
		Text = "光暗相依，日月同行",
	},
	[20108] = {
		Text = "汝是否想打破平衡？",
	},
	[20109] = {
		Text = "胆敢擅闯圣殿！",
	},
	[20110] = {
		Text = "(星光共鸣声—)",
	},
	[20111] = {
		Text = "黑夜，将吞噬光明…",
	},
	[20112] = {
		Text = "在永恒的混沌中迷失吧",
	},
	[20113] = {
		Text = "昼夜交替，永无止境",
	},
	[20114] = {
		Text = "圣殿的守护者，合而为一！",
	},
	[20115] = {
		Text = "(冰霜咆哮—)",
	},
	[20116] = {
		Text = "冻结一切的寒风啊！",
	},
	[20117] = {
		Text = "别挑战巨龙的威严！",
	},
	[20118] = {
		Text = "这片冰雪是吾之领土！",
	},
	[20119] = {
		Text = "凡人，感受极寒的绝望吧！",
	},
	[20120] = {
		Text = "(烈焰低吼—)",
	},
	[20121] = {
		Text = "这里将化为一片火海！",
	},
	[20122] = {
		Text = "感受龙之怒火吧！",
	},
	[20123] = {
		Text = "吾之鳞甲，坚不可摧！",
	},
	[20124] = {
		Text = "化为灰烬吧，入侵者！",
	},
	[20125] = {
		Text = "准备接受审判！",
	},
	[20126] = {
		Text = "你的灵魂有多重？",
	},
	[20127] = {
		Text = "你的未来…通往冥界！",
	},
	[20128] = {
		Text = "嘘…毋须多言…",
	},
	[20129] = {
		Text = "看来又是个罪人…",
	},
	[20130] = {
		Text = "(碰咚—碰咚—)",
	},
	[20131] = {
		Text = "杀戮模式—启动",
	},
	[20132] = {
		Text = "识别—识别失败？",
	},
	[20133] = {
		Text = "歼灭炮—瞄准中—",
	},
	[20134] = {
		Text = "指令错误—错误—",
	},
	[20135] = {
		Text = "哪来的坏孩子？",
	},
	[20136] = {
		Text = "礼物！礼物！礼物！",
	},
	[20138] = {
		Text = "你是…好孩子…？",
	},
	[20140] = {
		Text = "尘归尘，汝归土！",
	},
	[20142] = {
		Text = "来场亡灵派对？",
	},
	[20143] = {
		Text = "啧…活人的臭味…",
	},
	[20144] = {
		Text = "你的头我收下了！",
	},
	[20145] = {
		Text = "今日随机效果是…",
	},
	[20146] = {
		Text = "星辰坠落之时已至…",
	},
	[20147] = {
		Text = "跟随冥火一同飞翔…",
	},
	[20148] = {
		Text = "黑夜的羽翼将遮蔽天空！",
	},
	[20149] = {
		Text = "逃吧…在阴影之中颤抖…",
	},
	[20150] = {
		Text = "目标--危险---！",
	},
	[20151] = {
		Text = "最大--功率--",
	},
	[20152] = {
		Text = "和平--无法--？",
	},
	[20153] = {
		Text = "雷射--瞄准--",
	},
	[20154] = {
		Text = "实验体--反抗--？",
	},
	[20155] = {
		Text = "成为我的养分吧！",
	},
	[20156] = {
		Text = "来点毒蘑菇吗？",
	},
	[20157] = {
		Text = "是谁在森林捣乱？",
	},
	[20158] = {
		Text = "你…不是森林居民…",
	},
	[20160] = {
		Text = "太阳，将一切点亮",
	},
	[20161] = {
		Text = "月亮…消逝于黑暗…",
	},
	[20162] = {
		Text = "光暗相依，日月同行",
	},
	[20163] = {
		Text = "汝是否想打破平衡？",
	},
	[20164] = {
		Text = "胆敢擅闯圣殿！",
	},
	[20165] = {
		Text = "王怪发话占位",
	},
	[20166] = {
		Text = "王怪发话占位",
	},
	[20167] = {
		Text = "王怪发话占位",
