	},
	[30027] = {
		Text = "情感共鸣，星海震荡！ {0}，满载姬绊的至高星主，彻底点燃{1}之星际悸动！向这位姬绊星主致以无上敬意！ （全服同享礼盒待星主发送）",
	},
	[30028] = {
		Text = "情弦撩动，{0}携满盈姬绊，引导{1}那令人沉醉的星域！其共鸣之深，宛若星河点燃夜空！ （全服同享礼盒待星主发送）",
	},
	[30029] = {
		Text = "心电交织，又一星际佳话！ {0}温柔引导{1}之思绪狂潮，大舰长之名响彻星海！ （全服同享礼盒待星主发送）",
	},
	[30030] = {
		Text = "情感无需激昂，满盈之姬绊使其悸动星空；星海无需无垠，{0}之情使其共鸣！恭贺首位引导{1}的至高星主！ （全服同享礼盒待星主发送）",
	},
	[30031] = {
		Text = "思绪翻涌，后来者更胜前贤！ {0}以大舰长之情，成为第二位越{1}的星际先驱！ （全服同享礼盒待星主发送）",
	},
	[30032] = {
		Text = "悸动震星，第三位引导{1}的星主降临！ {0}以情与姬绊，书写不朽佳话！ （全服同享礼盒待星主发送）",
	},
	[30033] = {
		Text = "群星凝视，{0}如波频点燃{1}之星际迷雾！其共鸣宛若星主降临，众星为之狂热颂唱！ （全服同享礼盒待星主发送）",
	},
	[30034] = {
