	},
	[30035] = {
		Text = "情弦掠影，{0}触动{1}之思绪！这片星空因您的共鸣而震颤！ （全服同享礼盒待星主发送）",
	},
	[30036] = {
		Text = "孤寂退避，一传奇大舰长率先解{1}之感官结界！ {0}，您是星空下的不灭辉煌！ （全服同享礼盒待星主发送）",
	},
	[30037] = {
		Text = "悸动腾空，{0}集感官与姬绊，成为第二位引导{1}的至高星主！其共鸣耀眼夺目！ （全服同享礼盒待星主发送）",
	},
	[30038] = {
		Text = "心曲嘹亮，{0}温柔引导{1}之悸动！大舰长的佳话因您而更加辉煌！ （全服同享礼盒待星主发送）",
	},
	[30039] = {
