	[100640] = {
		Text = "1、从四处搜集不同的星体，可获得各种能力加成。\n2、消耗1个星体碎片解锁对应星体，消耗额外的星体碎片升级对应星体。\n3、可使用「星体燃素」进行升星，不同品质的星体所需的消耗量不同。\n4、星体满级后，溢出的星体碎片可分解成「星体燃素」，不同品质的星体分解后的获得量不同。",
