	[100643] = {
		Text = "1、搜集不同种类的星体，可点亮星体之间的连系，化为星座。\n2、每个星座中的所有星体达到相同星级时，可强化星座间的连系，获得更强的能力加成。",
	},
	[100644] = {
		Text = "点亮",
	},
	[100645] = {
		Text = "1、首次通过该难度的星球时，可以获得一次首通奖励。\n2、根据玩家所通过的最高难度，发送每日奖励。\n3、可挑战的星球将随伺服器天数逐渐开放；最新开放的几座星球会额外提升难度，供玩家挑战。",
	},
	[100646] = {
		Text = "1、每次召唤星体时，会增加「1点」祝福值。\n2、抽中「卓越品质」以上的星体时，将会清空祝福值。\n3、祝福值达最大值时，下一抽必定从「卓越品质」以上的星体中抽取一个做为奖励。",
