	[610101] = {
		Text = "说不定下次可以一起钓鱼呢。",
	},
	[610102] = {
		Text = "如果在房子旁盖一栋雪屋是不是很棒呢？",
	},
	[610103] = {
		Text = "不能让晨星先生总是担心我才行。",
	},
	[610110] = {
		Text = "和晨星先生一起，连爬山都变得很有趣。",
	},
	[610111] = {
		Text = "虽然白天也很棒，但还是喜欢夜晚的星空。",
	},
	[610112] = {
		Text = "这些狼近看还蛮可爱的呢，只要不要吃我就好了。",
