	},
	[610401] = {
		Text = "你居然按我家的门铃！好像没有什么不对……？",
	},
	[610402] = {
		Text = "那么喜欢撞的话，不如撞其他地方嘛～",
	},
	[610403] = {
		Text = "嘿嘿嘿……你也有反过来偷窥我的一天吗？",
	},
	[610410] = {
		Text = "对我的书有兴趣吗？我倒是比较喜欢实践呢嘿嘿嘿……",
	},
	[610411] = {
		Text = "你敢碰那个我就让你没办法下床！",
	},
	[610412] = {
		Text = "挑个喜欢的带走吗？还是想要把我带走也行喔～",
	},
	[610419] = {
		Text = "嘿嘿嘿……全喝下去了，感受到毁灭般的欲望吧。",
	},
	[610420] = {
		Text = "什么叫做没感觉，拿来我喝看看！",
	},
	[610421] = {
		Text = "你先等一下！别再喝了！先听我讲！",
	},
	[610501] = {
		Text = "居然怀疑我这个天才美少女吗？真是没眼光。",
	},
	[610502] = {
		Text = "要是真的有会后空翻的猫，我也想养呢。",
	},
	[610503] = {
		Text = "什么叫做骚扰，这叫正当的邀请，我可没有强迫你喔。",
	},
	[610510] = {
		Text = "哼哼，口气倒是不小嘛。",
	},
	[610511] = {
		Text = "凭助手你也想教训我吗？",
	},
	[610512] = {
		Text = "想要我让你？舔我的脚的话到不是不能考虑喔。",
	},
	[610519] = {
		Text = "生存状态良好，但是去帮我开冷气。",
	},
	[610520] = {
		Text = "好～热～喔～",
	},
	[610521] = {
		Text = "绝世美少女就算流出来的汗也是香的！",
	},
	[610601] = {
		Text = "那个就是那个啊，你怎么不知道那个是哪个？",
	},
	[610602] = {
		Text = "你是不是用李奥纳多偷作弊了？",
	},
	[610603] = {
		Text = "大力出奇迹是逼不得已的办法啦！",
	},
	[610610] = {
		Text = "五分钟引擎都可以转十万圈了，快起床！",
	},
	[610611] = {
		Text = "啊啊啊！小鸟！",
	},
	[610612] = {
		Text = "至少穿条裤子啊！",
	},
	[610619] = {
		Text = "看光光也不是第一次了吧？",
	},
	[610620] = {
		Text = "或许应该在船上加装缆车，就不用那么累了。",
	},
	[610621] = {
		Text = "其实船上的地板是很暖活的。",
	},
	[610701] = {
		Text = "唱歌的课题，已经非常完美，粉丝一号都看着的吧。",
	},
	[610702] = {
		Text = "跳舞确实是很难的，请协助我加强练习。",
	},
	[610703] = {
		Text = "单纯的游戏固然不错，但设定情境可以增进情趣。",
	},
	[610710] = {
		Text = "现在回家还太早了，真的不考虑爱情旅馆吗？",
	},
	[610711] = {
		Text = "没有什么是绝对不可能的，真的不去吗？",
	},
	[610712] = {
		Text = "我认为备案也相当不错，真的不考虑吗？",
	},
	[610719] = {
		Text = "三千次练习可以兑换三千次表演，粉丝一号，请加油",
	},
	[610720] = {
		Text = "你在说什么呢？我平常就是这样子的不是吗？",
	},
	[610721] = {
		Text = "练习不会结束，请继续加油，粉丝一号。",
	},
