	},
	[611101] = {
		Text = "真是可爱又充满恶趣味的回答呢。",
	},
	[611102] = {
		Text = "身上的谜团越多，就越有趣呢。",
	},
	[611103] = {
		Text = "我很期待喔，少年你的计划。",
	},
	[611110] = {
		Text = "可不能什么都用蛮力解决呢。",
	},
	[611111] = {
		Text = "潜行的技巧有待加强呦。",
	},
	[611112] = {
		Text = "你这……咳咳……失态了……",
	},
	[611119] = {
		Text = "能专心到什么时候呢？",
	},
	[611120] = {
		Text = "和魔女讨价还价可不是明智的决定喔。",
	},
	[611121] = {
		Text = "这种程度也没问题吗？那我可要用力啰。",
	},
